        } catch (Exception e) {
            try {
                Field f = clazz.getDeclaredField("isEnabled");
                f.setAccessible(true);
                return f.getBoolean(logger);
            } catch (Exception ex) {
                throw new RuntimeException(ex);
            }
        }
    }

    @Test
    public void testLogPolicy_PrintsWhenEnabled() {
        Map<String, String[][]> policy = new HashMap<>();
        String[][] rows = new String[][] {
