        } finally {
            System.out.flush();
            System.setOut(originalOut);
        }

        String output = outContent.toString();
        assertTrue(output.contains("alice"), "Output should contain policy value 'alice'");
        assertTrue(output.contains("data1"), "Output should contain policy value 'data1'");
        assertTrue(output.contains("bob"), "Output should contain policy value 'bob'");
        assertTrue(output.contains("data2"), "Output should contain policy value 'data2'");
    }

    @Test
    public void testLogPolicy_NoOutputWhenDisabled() {
