import java.lang.reflect.Field;
import java.util.*;

import static org.junit.jupiter.api.Assertions.*;

public class LoadPolicyLineTests {

    private List<String> getFirstPolicyValues(Model model) throws Exception {
        // Traverse the model object graph to find the first field named "policy"
        Deque<Object> stack = new ArrayDeque<>();
        Set<Object> seen = Collections.newSetFromMap(new IdentityHashMap<>());
        stack.push(model);

        while (!stack.isEmpty()) {
            Object current = stack.pop();
            if (current == null || seen.contains(current)) continue;
            seen.add(current);

            Class<?> cls = current.getClass();
            for (Field field : getAllFields(cls)) {
                field.setAccessible(true);
                Object value = field.get(current);
                if (value == null) continue;

                // If we found a policy field, extract the first policy rule
                if (field.getName().equals("policy") && value instanceof List) {
                    List<?> policies = (List<?>) value;
                    if (!policies.isEmpty()) {
                        Object firstRule = policies.get(0);
                        if (firstRule instanceof List) {
                            List<String> result = new ArrayList<>();
                            for (Object o : (List<?>) firstRule) result.add(o.toString());
                            return result;
                        }
                    }
                }

                // Otherwise, traverse deeper into collections/maps/objects
                if (value instanceof Collection) {
                    for (Object item : (Collection<?>) value) stack.push(item);
                } else if (value instanceof Map) {
                    for (Object item : ((Map<?, ?>) value).values()) stack.push(item);
                } else {
                    stack.push(value);
                }
            }
        }
        return null;
    }

    private List<Field> getAllFields(Class<?> cls) {
        List<Field> fields = new ArrayList<>();
        Class<?> current = cls;
        while (current != null) {
            fields.addAll(Arrays.asList(current.getDeclaredFields()));
            current = current.getSuperclass();
        }
        return fields;
    }

