        List<List<String>> noExistsPolicy = new ArrayList<>();
        for (List<String> rule : rules) {
            if (!this.model.hasPolicy(sec, ptype, rule)) {
                noExistsPolicy.add(rule);
            }
        }

        if (shouldPersist.getAsBoolean()) {
