import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.jupiter.api.Assertions.*;

public class StartAutoLoadPolicyTests {

    private static final AtomicInteger GLOBAL_LOAD_COUNT = new AtomicInteger(0);

    @BeforeEach
    public void resetCounters() {
        GLOBAL_LOAD_COUNT.set(0);
    }

    // Test subclass to override loadPolicy for counting
    static class TestSyncedEnforcer extends SyncedEnforcer {
        @Override
        public void loadPolicy() {
            GLOBAL_LOAD_COUNT.incrementAndGet();
        }

        public int getLoadCount() {
            return GLOBAL_LOAD_COUNT.get();
        }
    }

    private int getAutoLoadRunningValue(Object obj) {
        // Use reflection to access the AtomicInteger flag if present
        Class<?> cls = obj.getClass();
        while (cls != null) {
            for (java.lang.reflect.Field f : cls.getDeclaredFields()) {
                if (f.getType() == java.util.concurrent.atomic.AtomicInteger.class) {
                    f.setAccessible(true);
                    try {
                        return ((AtomicInteger) f.get(obj)).get();
                    } catch (IllegalAccessException ignored) {
                    }
                }
            }
            cls = cls.getSuperclass();
        }
        return -1;
    }

