    public void testStartAutoLoadPolicy_startsAndLoadsPolicy() throws Exception {
        TestSyncedEnforcer enforcer = new TestSyncedEnforcer();
        enforcer.startAutoLoadPolicy(20);

        // Wait for at least one policy load
        TimeUnit.MILLISECONDS.sleep(100);
        assertTrue(enforcer.getLoadCount() > 0, "loadPolicy should have been called at least once");

