                    String a = (String) args[0];
                    String b = (String) args[1];
                    graph.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
                    return null;
                } else if ("clear".equals(name)) {
                    graph.clear();
                    return null;
                } else if ("hasLink".equals(name)) {
                    String a = (String) args[0];
                    String b = (String) args[1];
                    List<String> adj = graph.get(a);
                    return adj != null && adj.contains(b);
