import org.junit.jupiter.api.Test;

import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BiPredicate;

import static org.junit.jupiter.api.Assertions.*;

public class MatchTests {

    @Test
    void testMatchWithCustomFunctionAndCaching() {
        AtomicInteger counter = new AtomicInteger(0);
        BiPredicate<String, String> func = (str, pattern) -> {
            counter.incrementAndGet();
            return str.equals("foo") && pattern.equals("bar");
        };

        DefaultRoleManager rm = new DefaultRoleManager(3, func, null);

        // First call should compute and cache the result
        boolean first = rm.match("foo", "bar");
        assertTrue(first, "Expected match to be true on first computation");
        assertEquals(1, counter.get(), "Predicate should be called exactly once on first computation");

        // Second call with same inputs should use cache and not recompute
        boolean second = rm.match("foo", "bar");
        assertTrue(second, "Expected match to be true on cached result");
        assertEquals(1, counter.get(), "Predicate should not be called again due to caching");

        // Different inputs should trigger a new computation
        boolean third = rm.match("foo", "baz");
        assertFalse(third, "Expected match to be false for different pattern");
        assertEquals(2, counter.get(), "Predicate should be called for a new input pair");
    }

    @Test
    void testMatchWithDefaultEquality() {
        DefaultRoleManager rm = new DefaultRoleManager(3);

        // When no custom matching function is provided, use default equality
        assertTrue(rm.match("abc", "abc"));
        assertFalse(rm.match("abc", "abd"));
        assertTrue(rm.match("", ""));
        assertFalse(rm.match("a", ""));
    }
}

